use std::env;
use std::fmt::Write as FmtWrite;
use std::fs;
use std::process;

struct Report {
    count: u64,
    name: String,
    note: String,
}

fn parse(data: &str) -> Result<Report, String> {
    let mut count: Option<u64> = None;
    let mut name: Option<String> = None;
    let mut note: Option<String> = None;
    for (line_number, raw_line) in data.lines().enumerate() {
        let line = raw_line.strip_suffix('\r').unwrap_or(raw_line);
        let (field, value) = line
            .split_once('\t')
            .ok_or_else(|| format!("malformed field on line {}", line_number + 1))?;
        match field {
            "count" => {
                if count.is_some() {
                    return Err("duplicate count field".to_string());
                }
                count = Some(
                    value
                        .parse::<u64>()
                        .map_err(|_| format!("invalid count on line {}", line_number + 1))?,
                );
            }
            "name" => {
                if name.is_some() {
                    return Err("duplicate name field".to_string());
                }
                name = Some(value.to_string());
            }
            "note" => {
                if note.is_some() {
                    return Err("duplicate note field".to_string());
                }
                note = Some(value.to_string());
            }
            other => return Err(format!("unknown field '{}'", other)),
        }
    }
    Ok(Report {
        count: count.ok_or_else(|| "missing count field".to_string())?,
        name: name.ok_or_else(|| "missing name field".to_string())?,
        note: note.ok_or_else(|| "missing note field".to_string())?,
    })
}

fn escape_json(value: &str) -> String {
    let mut escaped = String::with_capacity(value.len());
    for character in value.chars() {
        match character {
            '"' => escaped.push_str("\\\""),
            '\\' => escaped.push_str("\\\\"),
            '\u{08}' => escaped.push_str("\\b"),
            '\u{0c}' => escaped.push_str("\\f"),
            '\n' => escaped.push_str("\\n"),
            '\r' => escaped.push_str("\\r"),
            '\t' => escaped.push_str("\\t"),
            character if character <= '\u{1f}' => {
                write!(&mut escaped, "\\u{:04x}", character as u32).unwrap();
            }
            character => escaped.push(character),
        }
    }
    escaped
}

fn fail(message: impl AsRef<str>) -> ! {
    eprintln!("{}", message.as_ref());
    process::exit(1);
}

fn main() {
    let mut arguments = env::args();
    arguments.next();
    let path = arguments.next().unwrap_or_else(|| fail("missing report.tsv path"));
    let data = fs::read_to_string(&path)
        .unwrap_or_else(|error| fail(format!("cannot read '{}': {}", path, error)));
    let report = parse(&data).unwrap_or_else(|message| fail(message));
    let name = escape_json(&report.name);
    let note = escape_json(&report.note);
    println!(
        "{{\"count\":{},\"name\":\"{}\",\"note\":\"{}\"}}",
        report.count, name, note
    );
}
